# Original, self-contained graphs: hypothetical pure substance, fixed pressure,
# no decomposition, constant heating; not measurements from the source book.
def svg_doc(body):return '<svg xmlns="http://www.w3.org/2000/svg" width="720" height="400" viewBox="0 0 720 400"><rect width="720" height="400" fill="white"/><g font-family="sans-serif" font-size="22" fill="#111">'+body+'</g></svg>\n'
for n in range(1,15):
 mp=10+5*n;bp=110+5*n;a=2+n%3;b=a+2+n%4;c=b+3+n%3;d=c+4+n%4;end=d+2
 times=[0,a,b,c,d,end];temps=[mp-30,mp,mp,bp,bp,bp+30]
 def px(t):return 80+560*t/end
